CREATE FUNCTION [dbo].[LIST_SALARY22] (@Forms___F_MENU_BIM___MMO [int], @Forms___Baseknow___HOLA [int], @Forms___Baseknow___HSAY [int], @Forms___Baseknow___HJAZ [int], @Forms___Baseknow___HNAH [int], @Forms___Baseknow___HCON [int], @Forms___Baseknow___HKHA [int], @HOKMDATE [bigint], @Forms___Baseknow___SAGHFH [int], @Forms___Baseknow___HSANP [int], @Forms___Baseknow___HSHI [int], @Forms___Baseknow___YEA [smallint], @Forms___Baseknow___HEZA [int], @Forms___Baseknow___HBON [int], @Forms___Baseknow___HTAHOL [int]) RETURNS TABLE AS RETURN (SELECT LSE.CODE, LSE.PNAME, LSE.PFAMILY, LSE.PNAME + ' ' + LSE.PFAMILY AS PNPF, LSE.KHNOWNUM, LSE.FATHER, LSE.BIMEH_NUM, LSE.JOB, LSE.SEX, LSE.WSDAT, LSE.WEDATE, LSE.WDATE, LSE.DAYS, LSE.SALARY_DAYLY, CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY AS mosalary, CAST(LSE.HOME AS float) * CAST(LSE.DAYS AS float) AS hom, CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH END AS jmazsalmash, CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH + CASE WHEN @Forms___Baseknow___HOLA = -1 THEN ROUND(CAST(LSE.CHILDREN AS DECIMAL(18,6)) / (case when @Forms___F_MENU_BIM___MMO <7 then 31 else 30 end) * CAST(LSE.DAYS AS DECIMAL(18,2)), 0) ELSE 0 END END AS jamazsalmash, CASE WHEN LSE.DIHARD = 1 THEN 0 ELSE (CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH END) * 0.07 END AS bimper, (CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH + CASE WHEN @Forms___Baseknow___HOLA = -1 THEN ROUND(CAST(LSE.CHILDREN AS DECIMAL(18,6)) / (case when @Forms___F_MENU_BIM___MMO <7 then 31 else 30 end) * CAST(LSE.DAYS AS DECIMAL(18,2)), 0) ELSE 0 END END) - ((CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH END) * 0.07) - COALESCE(PM.MALIAT, 0) AS ghabel, LSE.CHILDREN AS chid, LSE.CONDITIONS, LSE.HAGHTAHOL, LSE.JAZB, LSE.SAYER, LSE.EZAFAH, LSE.PADASH, LSE.KASR_VAM, dbo.Umonth(LSE.WDATE) AS MM, (CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CAST(LSE.HOME AS float) * LSE.DAYS) * 0.07 AS bimper2, CASE WHEN LSE.TAB56 = 0 THEN 0 ELSE CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + CAST(LSE.HOME AS float) * LSE.DAYS END AS JAMMAHS20, LSE.DSW_IDPLC, LSE.DSW_NAT, LSE.DSW_BDATE, LSE.MaxOfHDATE, LSE.MAZMASH, CAST(CASE WHEN (CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + LSE.CHI + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH END) > @Forms___Baseknow___SAGHFH THEN ((CAST(LSE.DAYS AS float) * LSE.SALARY_DAYLY + LSE.CHI + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH END) - @Forms___Baseknow___SAGHFH) * 0.1 ELSE 0 END AS int) AS mali, LSE.TAB56, COALESCE(PM.MALIAT, 0) AS MALIAT, LSE.MELLICOD, LSE.ISCEO, (LSE.DAYS * LSE.SALARY_DAYLY + CASE WHEN LSE.DAYS = 0 THEN 0 ELSE LSE.MAZMASH END) * LSE.ISCEO AS H3BIM FROM dbo.LIST_SALARY_END(@Forms___F_MENU_BIM___MMO, @Forms___Baseknow___HOLA, @Forms___Baseknow___HSAY, @Forms___Baseknow___HJAZ, @Forms___Baseknow___HNAH, @Forms___Baseknow___HCON, @Forms___Baseknow___HKHA, @HOKMDATE, @Forms___Baseknow___HSANP, @Forms___Baseknow___HSHI, @Forms___Baseknow___YEA, @Forms___Baseknow___HEZA, @Forms___Baseknow___HBON,@Forms___Baseknow___HTAHOL) AS LSE LEFT OUTER JOIN dbo.PLIST_MALIAT AS PM ON LSE.WDATE = PM.WDATE AND LSE.CODE = PM.CODE WHERE LSE.BIMEH_NUM > 50 AND LSE.BIMEH_NUM IS NOT NULL AND dbo.Umonth(LSE.WDATE) = @Forms___F_MENU_BIM___MMO)
